/*
 * A227202  Least prime, q, greater than the previous prime, p, which is a
 *          primitive root of p; beginning with 2.
 * https://oeis.org/A227202
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = least prime q > previous prime p such that p is a
 *            primitive root of q; a(1) = 2
 * Range:     u8 n <= 29, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   grow_seq, mod_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by iteratively finding the next prime
   q for each prime p in the sequence.  */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/mod_pow.h"
#include "../utils/grow_seq.h"

static uint32_t *prime_arr = NULL;   /* list of primes (needed for factorisation) */
static size_t     prime_cnt = 0;     /* number of primes in the list */

/* ---------- prime generation (up to a fixed limit) ---------- */
static void init_primes(void)
{
    if (prime_arr != NULL) return;  /* already initialised */

    const uint32_t LIMIT = 2000000;   /* sufficient for n ≤ 10000 */
    uint8_t *is_prime = (uint8_t*)calloc(LIMIT + 1, 1);
    if (!is_prime) return;           /* allocation failed – unlikely */

    for (uint32_t i = 2; i <= LIMIT; ++i) is_prime[i] = 1;
    for (uint32_t i = 2; (uint64_t)i * i <= LIMIT; ++i)
        if (is_prime[i])
            for (uint32_t j = i * i; j <= LIMIT; j += i)
                is_prime[j] = 0;

    /* count primes to allocate array */
    size_t cnt = 0;
    for (uint32_t i = 2; i <= LIMIT; ++i)
        if (is_prime[i]) ++cnt;

    prime_arr = (uint32_t*)calloc(cnt, sizeof(uint32_t));
    if (!prime_arr) { free(is_prime); return; }

    size_t idx = 0;
    for (uint32_t i = 2; i <= LIMIT; ++i)
        if (is_prime[i]) prime_arr[idx++] = i;
    prime_cnt = cnt;
    free(is_prime);
}

/* ---------- simple primality test using the list of primes ---------- */
static bool is_prime_uint64(uint64_t n)
{
    if (n < 2) return false;
    for (size_t i = 0; i < prime_cnt; ++i) {
        uint32_t p = prime_arr[i];
        if ((uint64_t)p * (uint64_t)p > n) break;
        if (n % p == 0) return n == p;
    }
    return true;
}

/* ---------- next prime greater or equal to start ---------- */
static uint64_t next_prime_uint64(uint64_t start)
{
    if (start <= 2) return 2;
    if ((start & 1) == 0) ++start;
    for (uint64_t n = start; ; n += 2)
        if (is_prime_uint64(n)) return n;
}

/* ---------- check if base is a primitive root modulo mod ---------- */
static bool is_primitive_root(uint64_t base, uint64_t mod)
{
    uint64_t phi = mod - 1;
    uint64_t temp = phi;
    for (size_t i = 0; i < prime_cnt &&
                      (uint64_t)prime_arr[i] * (uint64_t)prime_arr[i] <= temp; ++i) {
        uint32_t p = prime_arr[i];
        if (temp % p == 0) {
            if (mod_pow((seq_t)base, phi / p, (seq_t)mod) == (seq_t)1)
                return false;
            while (temp % p == 0) temp /= p;
        }
    }
    if (temp > 1)
        if (mod_pow((seq_t)base, phi / temp, (seq_t)mod) == (seq_t)1)
            return false;
    return true;
}

/* ---------- memoised sequence calculation ---------- */
seq_t a(idx_t n)
{
    static seq_t *cache   = NULL;
    static size_t cache_cap = 0;
    static idx_t  last    = 0;          /* last computed index */

    init_primes();                      /* ensure primes list ready */

    if (n == 0) return (seq_t)0;        /* throwaway for out‑of‑range */

    while (last < n) {
        uint64_t q;                     /* prime to store as a(last+1) */
        if (last == 0)                  /* first entry */
            q = 2;
        else {
            uint64_t p = (uint64_t)cache[last];
            q = next_prime_uint64(p + 1);
            while (!is_primitive_root(p, q))
                q = next_prime_uint64(q + 1);
        }
        grow_seq(&cache, &cache_cap, last + 2); /* reserve space for index last+1 */
        cache[last + 1] = (seq_t)q;
        ++last;
    }
    return cache[n];
}
